SELECT json_build_object('album', (SELECT json_build_object('count',COUNT(*),'content_md5',md5(COALESCE(string_agg(row_to_json(t)::text, ',' ORDER BY "album_id"),''))) FROM public."album" AS t),'artist', (SELECT json_build_object('count',COUNT(*),'content_md5',md5(COALESCE(string_agg(row_to_json(t)::text, ',' ORDER BY "artist_id"),''))) FROM public."artist" AS t),'customer', (SELECT json_build_object('count',COUNT(*),'content_md5',md5(COALESCE(string_agg(row_to_json(t)::text, ',' ORDER BY "customer_id"),''))) FROM public."customer" AS t),'employee', (SELECT json_build_object('count',COUNT(*),'content_md5',md5(COALESCE(string_agg(row_to_json(t)::text, ',' ORDER BY "employee_id"),''))) FROM public."employee" AS t),'genre', (SELECT json_build_object('count',COUNT(*),'content_md5',md5(COALESCE(string_agg(row_to_json(t)::text, ',' ORDER BY "genre_id"),''))) FROM public."genre" AS t),'invoice', (SELECT json_build_object('count',COUNT(*),'content_md5',md5(COALESCE(string_agg(row_to_json(t)::text, ',' ORDER BY "invoice_id"),''))) FROM public."invoice" AS t),'invoice_line', (SELECT json_build_object('count',COUNT(*),'content_md5',md5(COALESCE(string_agg(row_to_json(t)::text, ',' ORDER BY "invoice_line_id"),''))) FROM public."invoice_line" AS t),'media_type', (SELECT json_build_object('count',COUNT(*),'content_md5',md5(COALESCE(string_agg(row_to_json(t)::text, ',' ORDER BY "media_type_id"),''))) FROM public."media_type" AS t),'playlist', (SELECT json_build_object('count',COUNT(*),'content_md5',md5(COALESCE(string_agg(row_to_json(t)::text, ',' ORDER BY "playlist_id"),''))) FROM public."playlist" AS t),'playlist_track', (SELECT json_build_object('count',COUNT(*),'content_md5',md5(COALESCE(string_agg(row_to_json(t)::text, ',' ORDER BY "playlist_id","track_id"),''))) FROM public."playlist_track" AS t),'track', (SELECT json_build_object('count',COUNT(*),'content_md5',md5(COALESCE(string_agg(row_to_json(t)::text, ',' ORDER BY "track_id"),''))) FROM public."track" AS t));
